import numpy as np, matplotlib.pyplot as plt, requests
def parse(pdb):
    ca={}; atoms={}
    for l in pdb.split("\n"):
        if l.startswith("ATOM"):
            an=l[12:16].strip(); ri=int(l[22:26])
            xyz=np.array([float(l[30:38]),float(l[38:46]),float(l[46:54])]); b=float(l[60:66])
            atoms.setdefault(ri,{})[an]=xyz
            if an=="CA": ca[ri]=(l[17:20].strip(),xyz,b)
    return ca,atoms
TM={"AIG1":[(13,30),(45,67),(88,110),(125,144),(157,179),(194,216)],
    "ADTRP":[(4,24),(47,67),(86,106),(120,140),(155,175),(190,210)]}
CAT={"AIG1":[("T43",43),("H131",131),("H134",134)],"ADTRP":[("T47",47),("H128",128),("H131",131)]}
ACC={"AIG1":"Q9NVV5","ADTRP":"Q96IZ2"}
fig,axes=plt.subplots(2,1,figsize=(13,8.5),sharex=False)
for ax,name in zip(axes,["AIG1","ADTRP"]):
    pdb=open(f"out/AF-{ACC[name]}-F1-model_v6.pdb").read() if False else requests.get(f"https://alphafold.ebi.ac.uk/files/AF-{ACC[name]}-F1-model_v6.pdb",timeout=120).text
    ca,atoms=parse(pdb); n=max(ca)
    vecs=[]
    for k,(s,e) in enumerate(TM[name]):
        pts=np.array([ca[i][1] for i in range(s,e+1)]); c=pts.mean(0)
        _,_,vt=np.linalg.svd(pts-c); axv=vt[0]
        if np.dot(pts[-1]-pts[0],axv)<0: axv=-axv
        vecs.append(axv*((-1)**k))
    nrm=np.mean(vecs,0); nrm/=np.linalg.norm(nrm)
    ctr=np.array([ca[i][1] for i in ca]).mean(0)
    z={i:float(np.dot(ca[i][1]-ctr,nrm)) for i in ca}
    mid=np.mean([(z[s]+z[e])/2 for s,e in TM[name]]); z={i:v-mid for i,v in z.items()}
    if z[1]>0: z={i:-v for i,v in z.items()}
    xs=sorted(z); ys=[z[i] for i in xs]; pl=[ca[i][2] for i in xs]
    ax.axhspan(-15,15,color="#f6e05e",alpha=.30,zorder=0)
    ax.axhline(0,color="#b7791f",lw=.8,ls=":",zorder=1)
    sc=ax.scatter(xs,ys,c=pl,cmap="viridis_r",vmin=50,vmax=100,s=11,zorder=3)
    for s,e in TM[name]:
        ax.plot(range(s,e+1),[z[i] for i in range(s,e+1)],color="#2d3748",lw=2.4,zorder=2)
    for lab,i in CAT[name]:
        ax.scatter([i],[z[i]],marker="*",s=320,color="#c53030",edgecolor="k",zorder=5)
        ax.annotate(lab,(i,z[i]),textcoords="offset points",xytext=(4,10),fontsize=11,color="#c53030",weight="bold")
    ax.annotate("N",(1,z[1]),textcoords="offset points",xytext=(-12,-2),fontsize=13,weight="bold")
    ax.annotate(f"C ({name} C-tail)",(n,z[n]),textcoords="offset points",xytext=(-20,-16),fontsize=11,weight="bold")
    ax.set_ylabel("position along membrane normal (Å)")
    ax.set_xlabel("residue number")
    ax.set_title(f"{name} (AlphaFold v6): 6 TM helices, N and C termini on the same (cytosolic) side, "
                 f"catalytic Thr/His buried in the bilayer", fontsize=11)
    ax.text(2, 20, "non-cytosolic side (ER lumen / extracellular)", fontsize=9, color="#4a5568")
    ax.text(2, -24, "cytosolic side", fontsize=9, color="#4a5568")
    ax.set_ylim(-45,32)
cb=fig.colorbar(sc, ax=axes, fraction=.025, pad=.01); cb.set_label("pLDDT")
plt.show()
